#!/usr/bin/env python3
"""Summarize accepted serialized C6 evidence, retaining all raw samples."""
from pathlib import Path
import json,statistics
ROOT=Path(__file__).resolve().parents[1];BASE=ROOT.parent/'docker-baseline/c6'
if (BASE/'report-summary.json').exists():raise SystemExit('Initial C6 report is already archived; read investigation/C6-BENCHMARKS.md. Do not replace preserved results.')
load=lambda p:json.loads((BASE/p).read_text())
warm=load('runs.json');fresh=load('fresh/runs.json');changed=load('changed/runs.json');hugo=load('hugo-changed/runs.json');routes=load('routes/results.json');assert len(warm)==15 and len(fresh)==15 and len(changed)==60 and len(hugo)==30 and len(routes)==6
assert sum(v['incremental_equals_full'] for v in changed)==12 and all(v['semantic_output_checked'] for v in changed+hugo)
assert all(v['incremental_equals_full'] for v in routes) and all(v.get('fresh_equals_accepted',v.get('publication_counts_verified',False)) for v in fresh)
med=lambda values:statistics.median(values)
summary={'warm':load('summary.json'),'fresh':load('fresh/summary.json'),'changed':load('changed/summary.json'),'hugo_changed':load('hugo-changed/summary.json'),'components':{}}
for project in ['hugo','docker','docker-agent']:
 rows=[v['components'] for v in warm if v['project']==project]
 if project=='hugo':summary['components'][project]={k:med(v[k]['wall_s'] for v in rows) for k in rows[0]}
 else:
  data={k:med(v[k] for v in rows) for k in ['nift_composition_s','asset_publication_s','total_s']}
  data.update({k:med(v['publication'][k] for v in rows) for k in ['markdown_exports_s','ancillary_s','search_s']})
  if project=='docker':
   data.update({k:med(v[k] for v in rows) for k in ['compatibility_wall_s','shell_prepare_s']});data['html_minification_s']=med(v['minification']['html_minification_s'] for v in rows);data['shortcode_expansion_s']=med(v['compatibility_expansion_ns']/1e9 for v in rows);data.update({k:med(v['renderer_components_ns'][k]/1e9 for v in rows) for k in rows[0]['renderer_components_ns']})
  else:data['composition_prepare_s']=med(v['composition_prepare_s'] for v in rows)
  summary['components'][project]=data
for project in ['docker','docker-agent']:
 summary.setdefault('changed_rss_kib',{})[project]={case:med(r['peak_rss_kib'] for r in changed if r['project']==project and r['case']==case) for case in summary['changed'][project]}
(BASE/'report-summary.json').write_text(json.dumps(summary,indent=2)+'\n')
lines=['# C6: serialized publication benchmarks and correctness','', 'All numbers are seconds. Five repetitions per project/mode/case; setup, clone, validation and restoration are outside timed intervals. The projects retain different maintained source models. No Nift implementation changes were made.','', '| Pipeline | Warm full median (range) | Fresh checkout median (range) | Largest measured process/phase RSS median, MiB |','|---|---:|---:|---:|']
for project in ['hugo','docker','docker-agent']:
 w=summary['warm'][project];f=summary['fresh'][project];lines.append(f"| {project} | {w['median_s']:.2f} ({w['min_s']:.2f}–{w['max_s']:.2f}) | {f['median_s']:.2f} ({f['min_s']:.2f}–{f['max_s']:.2f}) | {w['median_peak_rss_kib']/1024:.1f} |")
lines+=['','## Warm full components','', 'Component medians do not necessarily sum to the whole-pipeline median. Nested renderer timers diagnose the compatibility stage and must not be added to it again. Hugo exposes its complete generation/minification stage together; no synthetic Markdown-only Hugo timer is asserted.','']
for project,components in summary['components'].items():
 lines+=['### '+project,'','| Measured component | Median seconds |','|---|---:|']+[f'| {k} | {v:.4f} |' for k,v in components.items()]+['']
lines+=['## Changed inputs','', '| Edit | Hugo warm CLI full | docker incremental publication | docker-agent incremental publication |','|---|---:|---:|---:|']
for case in ['1-page','10-pages','100-pages','layout','navigation','metadata']:lines.append(f"| {case} | {summary['hugo_changed'][case]:.2f} | {summary['changed']['docker'][case]:.2f} | {summary['changed']['docker-agent'][case]:.2f} |")
lines+=['','Body cases edit the same published routes with the same sentinel paragraph, using Markdown versus HTML. Layout edits append a sentinel to the shared footer. Navigation edits alter a maintained sidebar label; Hugo uses linkTitle frontmatter and the migrations use their explicit navigation tree. Metadata edits change the Ubuntu page title; the HTML project maintains the associated title meta/schema fields directly. These are comparable publication intentions, not identical authoring operations.','', 'Hugo changed-input measurements invoke the full production CLI pipeline with warm application caches. They are **not Hugo server incremental measurements**. Nift pipelines use modified-mode dependencies and cached unchanged compiler/export work, followed by fresh search generation. Comparing these rows evaluates those workflows, not the best possible Hugo incremental server.','', 'Every migration case has five measured edits; its first edit is compared against a forced full rebuild, outside timing. All five edits restore every original publication hash. Addition, rename and deletion pass incremental/full equivalence in both projects, including body/anchor/TOC/literal syntax, navigation, download, sitemap and search, plus retirement of previous outputs. Tracking history is left to pipeline reconciliation; a test-fixture restoration-order error was corrected before acceptance.','', 'Fresh builds use full-history local committed checkouts, empty application state/output, prepared binaries/Node dependencies and the verified Python environment. All ten migration fresh publications are byte-identical to accepted output; all five native Hugo fresh publications verify route/download/search counts. OS caches are uncontrolled: **application-cold, not OS-cold**. Warm full migration runs force all compilation/composition/export stages; Hugo full runs use fresh destinations with warm resource/application caches.','', 'Builds run serially with no parallel build or browser capture from this experiment. Existing user desktop processes/services remain; host load observations are recorded in environment.json, and ranges expose observed variability. These are not CPU-isolated dedicated-host samples. Nift configuration is build-threads=-1, incremental-mode=modified, native minify-exts=[]; human minification is its separately timed standalone pinned Hugo-equivalent minifier. RSS values are GNU time process/phase maxima, not aggregate concurrent memory.','', 'The native Hugo reproduction is not an Alpine/BuildKit deployment measurement. Inputs/tool versions/provenance are in c6/environment.json and BASELINE.md. Maintained compiled frontend assets are copied by both migrations; changing the upstream asset toolchain is a separate maintenance task. Routine migration builds are offline. Dependency install/Go compilation/clone/hash validation are excluded from build timings.','', 'Reproduce with benchmarks/run.py, benchmarks/fresh.py, benchmarks/routes.py, benchmarks/changed.py and benchmarks/hugo-changed.py, sequentially. One incomplete Hugo attempt is excluded after /tmp quota exhaustion in upstream flatten tests. The task-owned Go download cache was relocated and subsequent upstream test temporaries use .cache/benchmark-tmp; source inputs and production commands are unchanged. Four successful one-page samples precede that temporary-directory change, and the recovered fifth plus later cases use it. Raw time/log files stay in the sibling docker-baseline/c6 evidence directory; compact samples and summaries are committed under investigation/c6. Do not run these scripts concurrently or change renderer/publication inputs during measurements.','']
text='\n'.join(lines)
for project in ['docker','docker-agent']:(ROOT.parent/project/'investigation/C6-BENCHMARKS.md').write_text(text)
print(json.dumps(summary,indent=2))
